using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Godot;

namespace DestructionRacing.Tracks;

/// <summary>The layouts of Crossroads Speedway (plan §7.3). The infield road course is a Should (§19).</summary>
public enum SpeedwayLayout { Oval, Figure8 }

/// <summary>
/// Crossroads Speedway as generated by tools/tracksmith/crossroads.py: both layouts' centrelines (forward, 1 m) with
/// their banking, start lines, pit lanes, the walls (the outer wall, the infield islands and each layout's barriers),
/// the terrain heightfield and the surface map. Loaded once and shared (sims, the look builder, the game).
/// </summary>
public sealed class SpeedwayData
{
    public const string DefaultPath = "res://assets/speedway/crossroads.json";
    private static SpeedwayData? _cached;

    public sealed class Layout
    {
        public required Vector2[] Points { get; init; }
        public required float[] Bank { get; init; }
        public float Length { get; init; }
        public float StartForward { get; init; }
        public float StartReverse { get; init; }
        public int Laps { get; init; }
        public Vector2? Crossover { get; init; }
        public float CrossoverRadius { get; init; }
        public required Vector2[] Pit { get; init; }
        public required Vector2[] PitBoxes { get; init; }
    }

    public required string Name { get; init; }
    public float RoadWidth { get; init; }
    public float WallThickness { get; init; }
    public required Layout Oval { get; init; }
    public required Layout Figure8 { get; init; }
    /// <summary>Wall polylines run with the pavement on their left; the wall stands to their right.</summary>
    public required Vector2[] OuterWall { get; init; }
    public required List<Vector2[]> Islands { get; init; }
    public required List<Vector2[]> OvalBarriers { get; init; }
    public required List<Vector2[]> Figure8Barriers { get; init; }
    public required Vector2[] CrossoverCorners { get; init; }
    public required Grid<float> Height { get; init; }
    public required Grid<byte> Surface { get; init; }

    public Layout Get(SpeedwayLayout layout) => layout == SpeedwayLayout.Oval ? Oval : Figure8;
    public List<Vector2[]> Barriers(SpeedwayLayout layout) => layout == SpeedwayLayout.Oval ? OvalBarriers : Figure8Barriers;

    private Rect2[]? _islandBounds;

    /// <summary>True when a world x, z lies inside an infield island (behind its wall, off every road and pit lane).</summary>
    public bool InsideIsland(float x, float z)
    {
        _islandBounds ??= Islands.Select(ring =>
        {
            var r = new Rect2(ring[0], Vector2.Zero);
            foreach (var p in ring) r = r.Expand(p);
            return r;
        }).ToArray();
        var q = new Vector2(x, z);
        for (int k = 0; k < Islands.Count; k++)
        {
            if (!_islandBounds[k].HasPoint(q)) continue;
            var ring = Islands[k];
            bool inside = false;
            for (int i = 0, j = ring.Length - 1; i < ring.Length; j = i++)
            {
                Vector2 a = ring[i], b = ring[j];
                if ((a.Y > z) != (b.Y > z) && x < a.X + (z - a.Y) * (b.X - a.X) / (b.Y - a.Y)) inside = !inside;
            }
            if (inside) return true;
        }
        return false;
    }

    /// <summary>Terrain height (bilinear) at a world x, z.</summary>
    public float HeightAt(float x, float z) => Height.Bilinear(x, z);

    /// <summary>Surface codes (crossroads.json "codes").</summary>
    public const byte Grass = 0, Asphalt = 1, Pit = 2, Concrete = 3, Dirt = 4;

    /// <summary>Tyre grip on the surface at a world x, z (asphalt 1).</summary>
    public float GripAt(float x, float z) => Surface.Nearest(x, z) switch
    {
        Asphalt or Pit => 1f,
        Concrete => 0.95f,
        Dirt => 0.8f,
        _ => 0.62f,
    };

    /// <summary>A regular x/z raster: cell (i, j) is at (X0 + i·Cell, Z0 + j·Cell), stored row by row (z major).</summary>
    public sealed class Grid<T> where T : struct
    {
        public float X0 { get; init; }
        public float Z0 { get; init; }
        public float Cell { get; init; }
        public int Nx { get; init; }
        public int Nz { get; init; }
        public required T[] Data { get; init; }

        public T Nearest(float x, float z)
        {
            int i = Math.Clamp((int)MathF.Round((x - X0) / Cell), 0, Nx - 1);
            int j = Math.Clamp((int)MathF.Round((z - Z0) / Cell), 0, Nz - 1);
            return Data[j * Nx + i];
        }
    }

    public static SpeedwayData Load(string path = DefaultPath)
    {
        if (_cached != null) return _cached;
        using var file = FileAccess.Open(path, FileAccess.ModeFlags.Read)
            ?? throw new InvalidOperationException($"Speedway data missing: {path} (run tools/tracksmith/crossroads.py)");
        using var doc = JsonDocument.Parse(file.GetAsText());
        var root = doc.RootElement;

        static Vector2 V(JsonElement e) => new(e[0].GetSingle(), e[1].GetSingle());
        static Vector2[] Line(JsonElement e)
        {
            var a = new Vector2[e.GetArrayLength()];
            int i = 0;
            foreach (var p in e.EnumerateArray()) a[i++] = V(p);
            return a;
        }
        static List<Vector2[]> Lines(JsonElement e)
        {
            var list = new List<Vector2[]>();
            foreach (var l in e.EnumerateArray()) list.Add(Line(l));
            return list;
        }
        static Layout ReadLayout(JsonElement e)
        {
            var bank = new List<float>();
            foreach (var b in e.GetProperty("bank").EnumerateArray()) bank.Add(b.GetSingle());
            var cross = e.GetProperty("crossover");
            var pit = e.GetProperty("pit");
            return new Layout
            {
                Points = Line(e.GetProperty("points")),
                Bank = bank.ToArray(),
                Length = e.GetProperty("length").GetSingle(),
                StartForward = e.GetProperty("start_forward").GetSingle(),
                StartReverse = e.GetProperty("start_reverse").GetSingle(),
                Laps = e.GetProperty("laps").GetInt32(),
                Crossover = cross.ValueKind == JsonValueKind.Null ? null : V(cross.GetProperty("point")),
                CrossoverRadius = cross.ValueKind == JsonValueKind.Null ? 0f : cross.GetProperty("radius").GetSingle(),
                Pit = Line(pit.GetProperty("points")),
                PitBoxes = Line(pit.GetProperty("boxes")),
            };
        }

        var layouts = root.GetProperty("layouts");
        var walls = root.GetProperty("walls");
        _cached = new SpeedwayData
        {
            Name = root.GetProperty("name").GetString() ?? "Speedway",
            RoadWidth = root.GetProperty("road_width").GetSingle(),
            WallThickness = root.GetProperty("wall_thickness").GetSingle(),
            Oval = ReadLayout(layouts.GetProperty("oval")),
            Figure8 = ReadLayout(layouts.GetProperty("figure8")),
            OuterWall = Line(walls.GetProperty("outer")),
            Islands = Lines(walls.GetProperty("islands")),
            OvalBarriers = Lines(walls.GetProperty("oval")),
            Figure8Barriers = Lines(walls.GetProperty("figure8")),
            CrossoverCorners = Line(root.GetProperty("crossover_corners")),
            Height = ReadGrid(root.GetProperty("heightfield"), bytes =>
            {
                var a = new float[bytes.Length / 4];
                Buffer.BlockCopy(bytes, 0, a, 0, bytes.Length);
                return a;
            }),
            Surface = ReadGrid(root.GetProperty("surface"), bytes => bytes),
        };
        return _cached;
    }

    private static Grid<T> ReadGrid<T>(JsonElement e, Func<byte[], T[]> decode) where T : struct
    {
        string path = e.GetProperty("file").GetString()!;
        byte[] bytes = FileAccess.GetFileAsBytes(path);
        if (bytes.Length == 0) throw new InvalidOperationException($"Speedway raster missing: {path}");
        var grid = new Grid<T>
        {
            X0 = e.GetProperty("x0").GetSingle(),
            Z0 = e.GetProperty("z0").GetSingle(),
            Cell = e.GetProperty("cell").GetSingle(),
            Nx = e.GetProperty("nx").GetInt32(),
            Nz = e.GetProperty("nz").GetInt32(),
            Data = decode(bytes),
        };
        if (grid.Data.Length != grid.Nx * grid.Nz)
            throw new InvalidOperationException($"Speedway raster {path}: {grid.Data.Length} values, expected {grid.Nx}×{grid.Nz}");
        return grid;
    }
}

internal static class GridExtensions
{
    public static float Bilinear(this SpeedwayData.Grid<float> g, float x, float z)
    {
        float u = Math.Clamp((x - g.X0) / g.Cell, 0f, g.Nx - 1.001f);
        float v = Math.Clamp((z - g.Z0) / g.Cell, 0f, g.Nz - 1.001f);
        int i = (int)u, j = (int)v;
        float fu = u - i, fv = v - j;
        float a = g.Data[j * g.Nx + i], b = g.Data[j * g.Nx + i + 1];
        float c = g.Data[(j + 1) * g.Nx + i], d = g.Data[(j + 1) * g.Nx + i + 1];
        return (a + (b - a) * fu) * (1f - fv) + (c + (d - c) * fu) * fv;
    }
}
